import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const signedPercent = (fallback = 0) => z.coerce.number().catch(fallback).transform(v => Number.isFinite(v) ? _.clamp(v, -100, 100) : fallback).prefault(fallback);
const text = (fallback = '未知') => z.coerce.string().catch(fallback).prefault(fallback);
const factState = z.enum(['未揭示', '已揭示', '误信已纠正']).catch('未揭示').prefault('未揭示');
const mistRow = z.record(z.string(), factState).catch({}).prefault({});
const relationEntry = z.object({ 好感度: signedPercent(50), 关系阶段: text('线上群友') }).passthrough().catch({ 好感度: 50, 关系阶段: '线上群友' }).prefault({ 好感度: 50, 关系阶段: '线上群友' });
const taskEntry = z.object({ 状态: z.enum(['未接', '进行中', '完成', '失败']).catch('未接').prefault('未接'), 进度备注: text('无') }).passthrough().catch({ 状态: '未接', 进度备注: '无' }).prefault({ 状态: '未接', 进度备注: '无' });

export const Schema = z.object({
  迷雾: z.record(z.string(), mistRow).catch({}).prefault({}),
  关系: z.record(z.string(), relationEntry).catch({}).prefault({}),
  登场: z.record(z.string(), z.coerce.boolean().catch(false).prefault(false)).catch({}).prefault({}),
  任务: z.record(z.string(), taskEntry).catch({}).prefault({}),
  user: z.object({ 姓名: text(), DC网名: text(), 性别: text(), 年龄: text(), 身份: text(), 住址: text(), 来历: text(), 外貌: text(), 其他: text('无') }).passthrough().catch({}).prefault({}),
  环境: z.object({ 日期: text(), 时段: z.enum(['黎明', '清晨', '上午', '正午', '下午', '傍晚', '夜间', '深夜', '凌晨', '时段未详']).catch('时段未详').prefault('时段未详') }).passthrough().catch({}).prefault({}),
  规则: z.object({ schema版本: z.literal('dc-neighbor-state-v1').catch('dc-neighbor-state-v1').prefault('dc-neighbor-state-v1'), 初始化完成: z.coerce.boolean().catch(false).prefault(false) }).passthrough().catch({}).prefault({})
}).passthrough();

$(() => { registerMvuSchema(Schema); });
